theorem remainingMultiplier_coprime_sieveProduct {N : ℕ} {t : Label}
    (ht : t ∈ selector N) :
    Nat.Coprime (t.1.2 * t.2.1 * t.2.2) (sieveProduct N t.1.2) :=

theorem residual_divisor_coprime_multiplier {N : ℕ} {t : Label}
    (ht : t ∈ selector N) {e : ℕ} (he : e ∈ (residualProduct N t).divisors) :
    Nat.Coprime (multiplier t) e :=

theorem p5z_marked_prime_product_fibre_card_le {rank N : ℕ}
    (S : Finset (Fin rank → Fin (N + 1))) (hS : S ⊆ Part3.labelledPrimeTuples rank N)
    (m : ℕ) : (S.filter (fun t => Part3.labelledProduct t = m)).card ≤ rank ^ rank :=

theorem p5z_markedProductWeight_nonneg {rank N : ℕ}
    (S : Finset (Fin rank → Fin (N + 1))) (W : (Fin rank → Fin (N + 1)) → ℝ)
    (hW : ∀ t ∈ S, 0 ≤ W t) (m : ℕ) : 0 ≤ p5z_markedProductWeight S W m :=
